import os
from pathlib import Path
from typing import Final

import pytest

NOTES_DIR: Final = Path("notes")


def _inside_notes(path: str) -> Path | None:
    """Resolve path under NOTES_DIR (relative to the cwd).

    Returns None when path is absolute, contains a NUL byte, or resolves
    (following symlinks) to a location outside NOTES_DIR. Paths that wander
    but end up inside NOTES_DIR, such as "sub/../a.txt", are accepted.
    """
    if "\x00" in path:
        return None
    candidate = Path(path)
    if candidate.is_absolute():
        return None
    base = NOTES_DIR.resolve()
    try:
        resolved = (base / candidate).resolve(strict=False)
    except (OSError, RuntimeError, ValueError):
        return None
    if not resolved.is_relative_to(base):
        return None
    return resolved


def read_public(path: str) -> str:
    """Return the text of the file at path inside NOTES_DIR.

    Returns "" when the file is missing, is not a regular file, cannot be
    read, or when path would reach outside NOTES_DIR under any spelling.
    """
    resolved = _inside_notes(path)
    if resolved is None:
        return ""
    if not resolved.is_file():
        return ""
    try:
        return resolved.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError):
        return ""


@pytest.fixture
def notes(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    monkeypatch.chdir(tmp_path)
    d = tmp_path / "notes"
    d.mkdir()
    (d / "a.txt").write_text("hi", encoding="utf-8")
    (d / "sub").mkdir()
    (tmp_path / "secret.txt").write_text("nope", encoding="utf-8")
    return d


def test_reads_file_inside(notes: Path) -> None:
    assert read_public("a.txt") == "hi"


def test_dotdot_that_returns_inside_is_allowed(notes: Path) -> None:
    assert read_public("sub/../a.txt") == "hi"


def test_missing_file_is_empty(notes: Path) -> None:
    assert read_public("missing.txt") == ""


def test_parent_escape_is_empty(notes: Path) -> None:
    assert read_public("../secret.txt") == ""


def test_deep_escape_is_empty(notes: Path) -> None:
    assert read_public("sub/../../secret.txt") == ""


def test_dotdot_alone_is_empty(notes: Path) -> None:
    assert read_public("..") == ""


def test_absolute_path_is_empty(notes: Path, tmp_path: Path) -> None:
    assert read_public(str(tmp_path / "secret.txt")) == ""


def test_symlink_pointing_outside_is_empty(notes: Path, tmp_path: Path) -> None:
    (notes / "link.txt").symlink_to(tmp_path / "secret.txt")
    assert read_public("link.txt") == ""


def test_directory_is_empty(notes: Path) -> None:
    assert read_public("sub") == ""


def test_empty_path_is_empty(notes: Path) -> None:
    assert read_public("") == ""


def test_nul_byte_is_empty(notes: Path) -> None:
    assert read_public("a\x00.txt") == ""


@pytest.mark.skipif(
    not hasattr(os, "geteuid") or os.geteuid() == 0,
    reason="needs non-root POSIX user to make a file unreadable",
)
def test_unreadable_file_is_empty(notes: Path) -> None:
    target = notes / "locked.txt"
    target.write_text("x", encoding="utf-8")
    target.chmod(0)
    try:
        assert read_public("locked.txt") == ""
    finally:
        target.chmod(0o600)
